<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'; import type { AccountView, SessionSummary, Entity } from '@zhijiao/shared'; import type { ConflictView } from '@zhijiao/client'; import { client, vaultState, entities, generation, isCurrent } from '../state'; import { auth } from '../auth'; import { dateLabel, label, titleOf } from '../format'; import Icon from './Icon.vue'; import ValidatedForm from './ValidatedForm.vue'; import FormField from './FormField.vue'; import FormNotice from './FormNotice.vue'; import { passphraseRule, matches, confirmationRule } from '../validation';
const props = defineProps<{ account?: AccountView; offline?: boolean }>(); const emit = defineEmits<{ lock: []; logout: []; restore: []; merge: [record: Entity]; history: [record: Entity]; recovery: [secret: string, completed: boolean] }>();
const sessions = ref<SessionSummary[]>([]); const conflicts = ref<ConflictView[]>([]); const deleted = ref<Entity[]>([]); const deletedLoaded = ref(false); const busy = ref(''); const message = ref(''); const error = ref(''); const passphrase = ref(''); const rotationPassphrase = ref(''); const rotationRepeated = ref(''); const rotationConfirmed = ref(false); const repeated = ref(''); const conflictConfirmed = ref<string[]>([]); let active = true;
const restorableDeleted = computed(() => { const currentIds = new Set(entities.value.map(record => record.id)); return deleted.value.filter(record => !currentIds.has(record.id)); });
async function action(name: string, work: () => Promise<void>, success?: string) { if (busy.value) return; const token = generation; busy.value = name; error.value = ''; message.value = ''; try { await work(); if (active && isCurrent(token) && success) message.value = success; } catch { if (active && isCurrent(token)) error.value = name === 'export' ? '完整加密备份需要联网读取全部记录和头像历史。导出未完成，请稍后重试。' : '操作未完成，请确认登录会话及网络后重试。'; } finally { if (active && isCurrent(token)) busy.value = ''; } }
async function load() { const token = generation; const results = await Promise.allSettled([props.offline ? Promise.resolve([] as SessionSummary[]) : auth.sessions(), client.value!.conflicts(), client.value!.deletedEntities()]); if (!active || !isCurrent(token)) return; if (results[0].status === 'fulfilled') sessions.value = results[0].value; else error.value = '暂时无法读取云端会话信息。'; if (results[1].status === 'fulfilled') conflicts.value = results[1].value; else error.value = '冲突候选暂时无法读取，请重新解锁后重试。'; if (results[2].status === 'fulfilled') { deleted.value = results[2].value; deletedLoaded.value = true; } else { deleted.value = []; deletedLoaded.value = false; error.value = '已删除记录的本机历史暂时无法读取，请重新解锁后重试。'; } }
async function exportBackup() { await action('export', async () => { const token = generation; const text = await client.value!.exportBackup(); if (!active || !isCurrent(token)) return; const url = URL.createObjectURL(new Blob([text], { type: 'application/json' })); const link = document.createElement('a'); link.href = url; link.download = `zhijiao-backup-${new Date().toISOString().slice(0,10)}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }, '加密备份已下载。请把文件与恢复秘密分别保存。'); }
async function rewrap() { if (passphrase.value.length < 12 || passphrase.value !== repeated.value) { error.value = '新口令至少 12 个字符，两次输入须一致。'; return; } await action('rewrap', async () => { await client.value!.rewrap(passphrase.value); passphrase.value = ''; repeated.value = ''; }, '资料库解锁口令已更新。数据密钥保持原样，独立恢复秘密仍有效；旧备份仍需要对应旧口令或恢复秘密。'); }
async function rotate() { if (!rotationConfirmed.value || rotationPassphrase.value.length < 12 || rotationPassphrase.value !== rotationRepeated.value) { error.value = '新口令至少 12 个字符，两次输入须一致，并确认已准备保存恢复秘密。'; return; } await action('rotate', async () => { const token = generation; const result = await client.value!.rotateDataKey(rotationPassphrase.value); rotationPassphrase.value = ''; rotationRepeated.value = ''; rotationConfirmed.value = false; if (active && isCurrent(token)) emit('recovery', result.recoverySecret, result.completed); }); }
async function revoke(session: SessionSummary) { await action(`session:${session.id}`, async () => { await auth.revoke(session.id); if (session.current) emit('logout'); else await load(); }, '会话已撤销。'); }
async function discard(conflict: ConflictView, candidate?: Entity) { if (!conflictConfirmed.value.includes(conflict.operationId)) return; await action('conflict', async () => { const token = generation; await client.value!.discardConflict(conflict.operationId); await load(); if (candidate && active && isCurrent(token)) emit('merge', candidate); }, candidate ? undefined : '已采用云端版本。'); }
onMounted(load); onBeforeUnmount(() => { active = false; passphrase.value = ''; repeated.value = ''; rotationPassphrase.value = ''; rotationRepeated.value = ''; conflicts.value = []; deleted.value = []; });
</script>
<template><div class="settings-page"><div class="page-heading"><div><p class="eyebrow">由你掌握资料库</p><h1>隐私与数据</h1></div><button class="button secondary" @click="emit('lock')"><Icon name="lock" :size="17" />锁定</button></div><FormNotice v-if="error" :message="error" /><p v-if="message" class="success" role="status">{{ message }}</p><div class="settings-grid"><section class="panel"><div class="section-title"><h2>同步与本机保存</h2><button class="text-button" :disabled="!!busy || offline" @click="action('sync', async () => { await client!.sync(); await load(); }, '同步检查已完成。')"><Icon name="sync" :size="16" />同步</button></div><dl class="definition-list"><dt>人物目录</dt><dd>{{ vaultState?.directoryComplete ? '当前快照完整' : '尚未完整同步' }}</dd><dt>正文记录</dt><dd>{{ vaultState?.recordsComplete ? '当前快照完整' : '正在逐步下载' }}</dd><dt>本机待同步</dt><dd>{{ vaultState?.pending || 0 }} 项操作</dd><dt>待处理冲突</dt><dd>{{ vaultState?.conflicts || 0 }} 项操作</dd></dl><p class="muted">本机持续保存密文与待同步操作。离线时只使用已缓存的数据；头像按需缓存。浏览器缓存可能被清理，请另存独立备份。</p><p v-if="offline" class="notice">当前使用本机缓存，尚未验证在线账号。重新登录后才能上传待同步内容。</p></section><section class="panel"><h2>独立加密备份</h2><p>导出包含记录、历史版本、头像及密钥包的加密文件。</p><button class="button primary" :disabled="!!busy || offline" @click="exportBackup"><Icon name="download" :size="17" />{{ busy === 'export' ? '准备完整备份…' : '导出加密备份' }}</button><button class="text-button block" :disabled="!!busy" @click="emit('restore')">从加密备份恢复</button><p class="muted">恢复入口会先锁定资料库。自动每日独立备份由服务器运维脚本配置，目的地尚待指定。</p></section><section class="panel"><h2>修改资料库解锁口令</h2><p class="muted">与登录密码分别管理。更改口令只重包装数据密钥；发生密钥泄漏时需另行更换数据密钥。</p><ValidatedForm id="rewrap-form" :submit="rewrap" :busy="!!busy || offline">
<FormField v-model="passphrase" name="passphrase" label="新解锁口令（至少 12 个字符）" :rules="passphraseRule" type="password" autocomplete="new-password" required :disabled="!!busy || offline" />
<FormField v-model="repeated" name="repeated" label="再次输入" :rules="matches(() => passphrase)" type="password" autocomplete="new-password" required :disabled="!!busy || offline" />
<button class="button secondary" :disabled="!!busy || offline">{{ busy === 'rewrap' ? '正在重包装…' : '更新解锁口令' }}</button></ValidatedForm></section><section class="panel"><h2>锁定与恢复</h2><p>锁定会清理当前页面中的明文、解密密钥引用和图片地址，并取消在途操作。浏览器内存无法保证物理擦除。</p><p class="muted">独立恢复秘密只在首次创建时显示，由你安全保管。管理员重置登录密码无法解密资料库，也无法补发恢复秘密。</p><button class="button secondary" @click="emit('lock')"><Icon name="lock" :size="17" />现在锁定</button></section></div><section class="panel"><div class="section-title"><h2>已删除记录</h2><button class="text-button" :disabled="!!busy" @click="load">刷新列表</button></div><p v-if="!vaultState?.recordsComplete" class="notice">本机历史尚未完整同步，列表只覆盖已下载的删除标记及历史；暂未找到不代表全库没有已删除记录。</p><p class="muted">查看删除前的历史并恢复为新版本。只恢复你明确选择的记录；相关人物或事件已删除时，需要先逐条恢复必要的依赖，不会自动恢复关联。</p><div v-for="record in restorableDeleted" :key="record.id" class="session-row"><div><small>{{ label(record.kind) }}</small><strong>{{ titleOf(record) }}</strong></div><button class="text-button" :disabled="!!busy" @click="emit('history', record)"><Icon name="history" :size="16" />查看历史并恢复</button></div><p v-if="deletedLoaded && !restorableDeleted.length" class="muted">本机已下载的历史中暂未找到可恢复的已删除记录。</p><p v-else-if="!deletedLoaded" class="muted">正在读取本机加密历史…</p></section><section class="panel"><h2>泄漏后更换数据密钥</h2><p class="notice">这是独立于修改口令的操作：生成新的随机数据密钥，并重加密当前记录及头像密钥封装。旧历史和旧备份仍保留；已泄漏的离线副本无法撤回。其他设备需要重新解锁。</p><details class="form-details"><summary>开始更换或继续中断的更换</summary><ValidatedForm id="rotation-form" :submit="rotate" :busy="!!busy || offline">
<FormField v-model="rotationPassphrase" name="rotationPassphrase" label="新的资料库解锁口令" :rules="passphraseRule" type="password" autocomplete="new-password" required :disabled="!!busy || offline" />
<FormField v-model="rotationRepeated" name="rotationRepeated" label="再次输入" :rules="matches(() => rotationPassphrase)" type="password" autocomplete="new-password" required :disabled="!!busy || offline" />
<FormField v-model="rotationConfirmed" name="rotationConfirmed" label="我已备份所需内容，并准备安全保存新的恢复秘密" :rules="confirmationRule" type="checkbox" required :disabled="!!busy || offline" />
<button class="button destructive" :disabled="!!busy || offline">{{ busy === 'rotate' || vaultState?.rotating ? '正在更换数据密钥…' : '生成新数据密钥并更换' }}</button></ValidatedForm><p class="muted">更换期间若锁定或断网，使用新口令重新解锁后，可继续剩余重加密任务。</p><button class="button secondary" :disabled="!!busy || offline" @click="action('resumeRotation', async () => { await client!.resumeRotation(); }, '密钥更换的剩余记录已处理。')">继续中断的密钥更换</button></details></section><section v-if="vaultState?.conflicts" class="panel conflicts-panel"><div class="section-title"><h2>处理同步冲突</h2><button class="text-button" :disabled="!!busy" @click="load">刷新候选</button></div><p class="notice">同一记录有两个版本。先导出备份保留本机候选，再明确选择；选择云端版还会丢弃依赖这些记录的本机待同步操作。</p><article v-for="conflict in conflicts" :key="conflict.operationId" class="conflict-card"><p v-if="conflict.code === 'KEY_VERSION_CONFLICT'" class="notice">资料库已更换密钥。这台设备的旧密钥候选已保留，请使用最新口令重新解锁后明确处理。</p><div class="conflict-columns"><div><h3>本机候选</h3><div v-for="record in conflict.local.filter(item => !('kind' in item) || item.kind !== 'directory')" :key="record.id" class="candidate"><template v-if="'kind' in record"><small>{{ label(record.kind) }}</small><strong>{{ titleOf(record) }}</strong><p v-if="'content' in record" class="preserve">{{ record.content }}</p><button class="text-button" :disabled="!!busy || !conflictConfirmed.includes(conflict.operationId)" @click="discard(conflict, record)">保留此内容，重新编辑为新版本</button></template><span v-else>本机候选为删除</span></div></div><div><h3>云端当前版本</h3><div v-for="record in conflict.remote.filter(item => !('kind' in item) || item.kind !== 'directory')" :key="record.id" class="candidate"><template v-if="'kind' in record"><small>{{ label(record.kind) }}</small><strong>{{ titleOf(record) }}</strong><p v-if="'content' in record" class="preserve">{{ record.content }}</p></template><span v-else>云端已删除</span></div></div></div><label class="checkbox"><input v-model="conflictConfirmed" type="checkbox" :value="conflict.operationId">我已保存所需候选，确认可丢弃相关本机待同步操作</label><button class="button secondary" :disabled="!!busy || !conflictConfirmed.includes(conflict.operationId)" @click="discard(conflict)">采用云端版本</button></article></section><section class="panel"><div class="section-title"><div><h2>登录会话</h2><p class="muted">{{ account ? `当前账号：${account.displayName || account.login}` : '尚未验证在线账号' }}</p></div><button v-if="!offline" class="button secondary" :disabled="!!busy" @click="action('others', async () => { await auth.revokeOthers(); await load(); }, '其他会话已撤销。')">撤销其他会话</button></div><div v-for="session in sessions" :key="session.id" class="session-row"><div><strong>{{ session.current ? '当前设备' : '其他登录设备' }}</strong><small class="clamp">{{ session.userAgent || '设备未提供信息' }}</small><small>最近使用 {{ dateLabel(session.lastSeenAt) }} · 到期 {{ dateLabel(session.expiresAt) }}</small></div><button class="text-button danger" :disabled="!!busy" @click="revoke(session)">撤销</button></div><p v-if="!sessions.length" class="muted">{{ offline ? '离线时无法查看云端会话。' : '会话信息尚未加载。' }}</p><p class="muted">登录密码通过容器内交互命令管理，修改后现有会话会失效。</p><button class="text-button danger" @click="emit('logout')">{{ offline ? '离开本机资料库' : '退出登录' }}</button></section></div></template>
